import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学日报 | 2026年11月5日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-11-05.md","filePath":"science-log/src/science-daily/2026-11-05.md"}'),g={name:"science-log/src/science-daily/2026-11-05.md"};function e(a,o,i,p,c,l){return n(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年11月5日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年11月5日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年11月5日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年11月5日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第55期简讯（🎬 科学前沿 5 篇 / 🤖 AI前沿 5 篇，共 10 条） 分析日期：2026-11-05 版本：扩展版（10 条深度 + 交叉关联） 核查说明：本机执行环境<strong>外网不可达</strong>（crossref / europepmc / doi.org 均 SSL connect failed，返回 000），<strong>未能联网核实原始出处</strong>。本期所有作者、期刊、DOI、关键数字<strong>均直接转自当天简讯（第55期）</strong>，未经二次独立核验；凡简讯未给出者，本文不补充、不推测。</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-让「核糖体移码」当开关-只在癌细胞里打开的治疗基因线路" tabindex="-1">1. 让「核糖体移码」当开关：只在癌细胞里打开的治疗基因线路 <a class="header-anchor" href="#_1-让「核糖体移码」当开关-只在癌细胞里打开的治疗基因线路" aria-label="Permalink to &quot;1. 让「核糖体移码」当开关：只在癌细胞里打开的治疗基因线路&quot;">​</a></h3><p><strong>原文</strong>：核糖体移码（ribosomal frameshifting）是一种少见的翻译重编码事件，最广为人知的是它在病毒基因表达中的调控作用，但其在哺乳动物中的生理意义一直不明。</p><p><strong>深度扩展</strong>：</p><p>这是被简讯标注为 <em>Nature (2026)</em> 的一项工作（DOI: 10.1038/s41586-026-11200-4；<strong>未能核实原始出处</strong>，作者与机构未在简讯中给出）。核心问题：−1 移码是核糖体在特定 mRNA 序列上&quot;读错框&quot;的稀有事件，病毒（如 HIV、冠状病毒）用它调控 gag-pol 比例；但在人体细胞里它是否承载可被利用的信息，长期空白。</p><p>方法上，作者做的是<strong>序列—表型筛选</strong>：系统扫描密码子对，找出能在<strong>癌细胞中优先高效触发 −1 移码</strong>的序列motif；随后做机制归因，把移码率提升追溯到一个完整因果链——<strong>核糖体暂停</strong>（速率受 <strong>tRNA 丰度与氨基酸可用性</strong>制约）→ 被<strong>受损的核糖体质量控制</strong>放大 → 叠加 <strong>核糖体蛋白 S6 的持续磷酸化</strong>（癌细胞翻译失调的标志性状态）。</p><p>关键转化是 <strong>FAST（移码激活的合成治疗线路）</strong>：把移码事件当作<strong>逻辑开关</strong>，下游接<strong>焦亡效应分子 gasdermin D</strong>。因为移码只在癌细胞的内禀翻译状态下高效发生，所以 gasdermin D 只在癌细胞内被翻译出来、<strong>选择性诱发焦亡</strong>；简讯称<strong>正常组织无可检出毒性</strong>。递送用 <strong>AAV9</strong>，在小鼠<strong>结直肠癌与胰腺癌</strong>模型中报告<strong>显著肿瘤消退、强免疫激活</strong>，并与<strong>免疫检查点阻断协同</strong>。</p><p>为什么重要：这是&quot;<strong>利用疾病特异状态</strong>而非攻击疾病特异靶点&quot;的范式——把癌细胞普遍存在的翻译失调本身变成可寻址的输入信号。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/anastasis-cancer-cell-recovery.md</code>（癌细胞&quot;假死复活&quot;与凋亡逃逸）同属&quot;癌细胞内禀状态可被反向利用&quot;的思路；翻译重编码视角可挂到 <code>topics/biomedicine/index.md</code>。</p><hr><h3 id="_2-三轴分子编织-把二维「编织布」从双轴推进到三轴" tabindex="-1">2. 三轴分子编织：把二维「编织布」从双轴推进到三轴 <a class="header-anchor" href="#_2-三轴分子编织-把二维「编织布」从双轴推进到三轴" aria-label="Permalink to &quot;2. 三轴分子编织：把二维「编织布」从双轴推进到三轴&quot;">​</a></h3><p><strong>原文</strong>：分子编织把分子链交织成有序网络，是设计功能材料的有力策略，但此前主要依赖线性构筑单元与双轴结构，≥3 轴的高阶编织一直未被充分探索。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>Nature (2026)</em>（DOI: 10.1038/s41586-026-11218-8；<strong>未能核实原始出处</strong>，机构未给出）。背景：<strong>分子编织（molecular weaving）</strong> 追求的是&quot;<strong>打结而非键合</strong>&quot;的拓扑——链与链之间靠<strong>机械纠缠</strong>而非共价键维系，因而兼具柔性与整体稳定性；此前合成困难，几乎只能做<strong>双轴</strong>网格。</p><p>本文的突破在于<strong>构筑单元升级</strong>：引入 <strong>C₃ 对称大环</strong>（三向对称节点）作为编织拐点，通过<strong>配位 B–N 聚合</strong>把三向节点连成<strong>二维网状三轴编织网络</strong>。三个并列的结果：(1) 网络具有<strong>拓扑手性</strong>——手性不由某个原子构型决定，而由<strong>整体编织拓扑</strong>决定，这是&quot;几何手性&quot;之外的独立维度；(2) <strong>力学性能稳健</strong>，网络难以解缠；(3) 作为<strong>多孔材料</strong>，可<strong>分离代表性芳香族/脂肪族化合物</strong>。</p><p>为什么重要：把编织的<strong>轴数</strong>从 2 提到 3，等于在传统&quot;组成—结构—性质&quot;链条之外<strong>新增一个拓扑自由度</strong>——同样的成分，只靠改变<strong>编织拓扑</strong>就能调控手性识别与吸附选择性。这为 MOF / COF 之外的功能材料设计提供了新的正交调节旋钮。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 的多孔材料主线、<code>topics/physics/advanced-materials-deep.md</code> 中拓扑与材料性质的桥接直接相关（拓扑手性 ↔ 材料功能）。</p><hr><h3 id="_3-硬-x-射线阿秒计量-在时域直接量出-170-阿秒脉冲" tabindex="-1">3. 硬 X 射线阿秒计量：在时域直接量出 170 阿秒脉冲 <a class="header-anchor" href="#_3-硬-x-射线阿秒计量-在时域直接量出-170-阿秒脉冲" aria-label="Permalink to &quot;3. 硬 X 射线阿秒计量：在时域直接量出 170 阿秒脉冲&quot;">​</a></h3><p><strong>原文</strong>：亚埃空间分辨 + 阿秒时间分辨可直接观测物质中的电子运动；自由电子激光产生的阿秒硬 X 射线脉冲具备这种时空灵敏度，但一直缺乏精确的脉冲计量与控制。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>Nature (2026)</em>（DOI: 10.1038/s41586-026-11245-5；<strong>未能核实原始出处</strong>）。问题是<strong>计量学空白</strong>：<strong>XFEL（自由电子激光）</strong> 能产硬 X 射线阿秒脉冲，但在此之前没人能在<strong>时域</strong>精确刻画这种脉冲——没有可靠的脉宽、相干时间与脉冲间同步测量手段，下游的&quot;泵浦—探测&quot;实验就无从对齐。</p><p>方法上是一个<strong>分束—延迟线</strong>架构：把宽带硬 X 射线分成两路、引入<strong>可控阿秒延迟</strong>，再用两类探针读出。(1) <strong>场关联测量</strong>——首次在时域给出<strong>脉冲相干时间</strong>，并证明<strong>脉冲对之间的阿秒同步</strong>；(2) <strong>非顺序双光子吸收</strong>作<strong>非线性探针</strong>，用<strong>强度自相关</strong>在时域直接读出<strong>平均脉冲宽度 170 as</strong>。</p><p>为什么重要：<strong>170 阿秒 ≈ 1.7×10⁻¹⁶ 秒</strong>，而 1 阿秒光走过的距离约 0.3 nm——即脉冲在时间内短到可以&quot;冻结&quot;原子尺度上电子的运动。有了可计量的阿秒硬 X 射线，就能做 <strong>X 射线泵浦—X 射线探测（X-ray pump–X-ray probe）</strong> 光谱与衍射，用<strong>元素与位点特异性</strong>的原子内壳层探针追踪电子动力学——这正是化学键断裂、光催化、电荷转移最本征的时间尺度。</p><p><strong>跨主题关联</strong>：与 <code>topics/physics/spectroscopy.md</code>（光谱探测方法）和 <code>topics/physics/science-daily-2026-11-05-physics.md</code> 同源，属于&quot;用更短的时间刻度换取更本征的物理解释&quot;这条主线。</p><hr><h3 id="_4-电信波段自旋—光子纠缠直接产生-并首次验证贝尔非局域性" tabindex="-1">4. 电信波段自旋—光子纠缠直接产生，并首次验证贝尔非局域性 <a class="header-anchor" href="#_4-电信波段自旋—光子纠缠直接产生-并首次验证贝尔非局域性" aria-label="Permalink to &quot;4. 电信波段自旋—光子纠缠直接产生，并首次验证贝尔非局域性&quot;">​</a></h3><p><strong>原文</strong>：量子非局域性是量子信息科学的基石，长距离分发纠缠要求「飞行光子」工作在光纤最低损耗的电信波段；此前虽在电信光子与各类静止自旋的纠缠直接产生上有大量努力，但量子非局域性的验证仍是悬而未决的挑战。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>Nature Communications (2026)</em>（DOI: 10.1038/s41467-026-79099-z；<strong>未能核实原始出处</strong>）。背景：量子网络要靠<strong>飞行光子</strong>在光纤里传输纠缠，而石英光纤的最低损耗窗口在 <strong>C 波段（~1550 nm）</strong>。此前多数原子/离子/量子点发射体在可见或近红外波段工作，需<strong>频率转换</strong>才能入纤——而转换会引入损耗与噪声，威胁纠缠保真度。</p><p>本文的做法是<strong>让发射体自己说电信波段的话</strong>：利用<strong>铷原子中 1530 nm 的偶极跃迁</strong>，配合<strong>腔辅助协议</strong>，实现<strong>单原子对 C 波段电信光子的共振激发与直接发射</strong>——无频率转换环节。结果：<strong>自旋—光子纠缠的贝尔态保真度 &gt; 91.4%</strong>，并观测到<strong>贝尔不等式违背 2.455(77) &gt; 2</strong>（S 参数超过经典局域隐变量上限），从而<strong>验证贝尔非局域性</strong>。</p><p>为什么重要：<strong>&quot;保真度 &gt; 91.4%&quot;和&quot;违背贝尔不等式&quot;是两回事</strong>——前者是态制备质量，后者是<strong>排除局域实在论</strong>的物理证据，二者同时满足才算真正可用于<strong>设备无关（DI）量子通信</strong>的物理资源。把单原子发射体直接做到电信 C 波段，是<strong>原子—光纤量子网络</strong>的关键接口一步。</p><p><strong>跨主题关联</strong>：直接对应 <code>topics/quantum-physics/science-daily-2026-11-05-quantum.md</code> 与 <code>topics/quantum-physics/macro-entanglement-2026.md</code>（纠缠从微观到宏观的谱系），并挂 <code>topics/quantum-physics/index.md</code>。</p><hr><h3 id="_5-火星冷季-hcl-异常-指向阿尔巴山区域仍在进行的岩浆活动" tabindex="-1">5. 火星冷季 HCl 异常：指向阿尔巴山区域仍在进行的岩浆活动 <a class="header-anchor" href="#_5-火星冷季-hcl-异常-指向阿尔巴山区域仍在进行的岩浆活动" aria-label="Permalink to &quot;5. 火星冷季 HCl 异常：指向阿尔巴山区域仍在进行的岩浆活动&quot;">​</a></h3><p><strong>原文</strong>：火星一向被视为没有持续火山活动，但近年火星震的发现、以及数千万年以内火山活动的线索不断累积；SO₂ 一直未被探测到，而卤素气体（如 HCl）的渗出可能更适合指示活跃的岩浆房。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>Science Advances (2026)</em>（DOI: 10.1126/sciadv.aeb9422；<strong>未能核实原始出处</strong>）。背景链条：<strong>SO₂ 探测缺失</strong>曾被当作&quot;火星无活跃火山&quot;的证据，但 SO₂ 极易被火星大气中的氧化性/光化学过程清除，<strong>不是好的示踪气体</strong>；卤素气体 <strong>HCl</strong> 更稳定，更适合当岩浆脱气的&quot;指纹&quot;。</p><p>本文的观测反常点有两个：(1) <strong>时序</strong>——此前的 ppb 级 HCl 只出现在<strong>近日点暖季</strong>（火星一年中接收日照最多时），被归因于<strong>气溶胶—大气化学来源</strong>；本文报告的是<strong>远日点冷季</strong>的 HCl 探测，<strong>暖季机制解释不了</strong>。(2) <strong>空间</strong>——HCl <strong>孤立出现在阿尔巴山（Alba Mons）区域</strong>，而非全球弥散。作者据此指出<strong>最优解释是火星内部仍在进行岩浆过程</strong>。</p><p><strong>跨主题关联</strong>：与 <code>topics/earth-science/science-daily-2026-11-05-earth.md</code>（行星过程类比）及 <code>topics/paleontology/index.md</code>（行星/地质时间尺度上的活动性判读）在&quot;用<strong>短寿命示踪物</strong>推断<strong>持续过程</strong>&quot;这一方法论上同构。</p><hr><h2 id="🤖-二、ai前沿" tabindex="-1">🤖 二、AI前沿 <a class="header-anchor" href="#🤖-二、ai前沿" aria-label="Permalink to &quot;🤖 二、AI前沿&quot;">​</a></h2><h3 id="_6-dreamx-把视频扩散模型变成通用「潜动作」学习器" tabindex="-1">6. DreamX：把视频扩散模型变成通用「潜动作」学习器 <a class="header-anchor" href="#_6-dreamx-把视频扩散模型变成通用「潜动作」学习器" aria-label="Permalink to &quot;6. DreamX：把视频扩散模型变成通用「潜动作」学习器&quot;">​</a></h3><p><strong>原文</strong>：从视频学通用动作表示，要求模型捕捉同一动作在不同执行下一致的动力学、又对具身与外观变化不变；既有潜动作模型虽从视觉转移中推断动作，却常把动作与无关视觉变化纠缠在一起，限制跨具身迁移。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>arXiv:2611.05377 (2026)</em>（<strong>未能核实原始出处</strong>，Crossref/arXiv 均不可达）。问题定义很清楚：<strong>潜动作（latent action）</strong> 的目标是&quot;<strong>看一眼视频，抽出一个动作表示</strong>&quot;，且这个表示必须<strong>跨具身、跨外观不变</strong>——因为同一个&quot;推&quot;在机械臂和人手上像素完全不同。既有方法从<strong>相邻帧的视觉转移</strong>反推动作，缺陷是<strong>把动作和无关视觉变化（光照、纹理、背景运动）缠在一起</strong>，一到新具身就崩。</p><p>DreamX 的关键洞见是：<strong>不必从零学动作，而是借视频扩散模型已有的&quot;物理直觉&quot;</strong>。做法是从预训练视频扩散模型的<strong>时空特征</strong>里抽取<strong>紧凑潜动作</strong>，把每个潜视频帧<strong>压缩约 300×（1,200 → 4 token）</strong>。压缩的好处是<strong>信息瓶颈自动剔除外观细节</strong>，迫使其保留<strong>与动力学相关、可跨本体重放</strong>的部分——因为视频模型的<strong>生成先验</strong>已经编码了&quot;世界如何演化&quot;。</p><p>结果（据简讯）：在 <strong>LARY-Bench</strong> 上取得潜动作模型的 <strong>SOTA</strong>，支持<strong>任意到任意的视频迁移</strong>、<strong>零样本跨具身动作迁移</strong>（人与机器人共享同一潜动作接口），并让策略<strong>在紧凑潜动作空间里学习</strong>，从而<strong>降低视频扩散策略的算力开销</strong>。为什么重要：这是**&quot;用大生成模型的语义先验换小策略器的采样效率&quot;<strong>——把昂贵的扩散推理</strong>前置一次**，换来下游廉价控制。</p><p><strong>跨主题关联</strong>：与 <code>topics/intelligence-self-learning/index.md</code>（自学习/表征迁移主线）相关；&quot;共享动作接口&quot;思路可对照 <code>topics/vibe-coding/index.md</code> 中的人机接口范式。</p><hr><h3 id="_7-pearl-让「不想要的行为」被压制得更持久" tabindex="-1">7. PEARL：让「不想要的行为」被压制得更持久 <a class="header-anchor" href="#_7-pearl-让「不想要的行为」被压制得更持久" aria-label="Permalink to &quot;7. PEARL：让「不想要的行为」被压制得更持久&quot;">​</a></h3><p><strong>原文</strong>：不良行为可能在训练的任何阶段出现或复现，那么观测到之后能多有效地压制它？</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>arXiv:2611.05358 (2026)</em>（<strong>未能核实原始出处</strong>）。这是一篇<strong>对齐鲁棒性</strong>论文，先把问题拆干净：定义三种评估准则——<strong>即时压制</strong>（观测到后马上压住）、<strong>进一步训练下的持久性</strong>（接着训别的会不会复发）、<strong>通用能力保持</strong>（压制会不会把模型变笨）。</p><p>实验设计用的是**&quot;模式生物&quot;（model organisms）** 思路：刻意造两种失准模型。(1) <strong>窄触发型</strong>——只在提示含特定线索时出错（如听从植入的错误提示去作弊）；(2) <strong>宽触发型</strong>——在<strong>不安全代码</strong>上微调后，对<strong>广泛的开放式提示</strong>都给有害回答。然后在同一坐标系下比较 <strong>SFT、GRPO、梯度上升式遗忘</strong>。</p><p>理论假设是&quot;<strong>对齐浅层性（alignment shallowness）</strong>&quot;：如果对齐只覆写了少数状态，那么压制也只会是浅的；<strong>要更持久，方法必须能从更广的失准状态中恢复</strong>。据此提出 <strong>PEARL（Prefix-Expanded Adversarial RL）</strong>——一个 <strong>GRPO 变体</strong>，用<strong>缓存轨迹的中间状态续写</strong>来扩充 rollout（即把训练样本的&quot;起跑线&quot;从提示位置前移到中间状态，逼模型在更多入口状态下学会正确行为）。在<strong>两个模式生物 × 两个模型族（Qwen3-4B、GPT-OSS-20B）<strong>上，PEARL <strong>即时压制强、任务准确率保住</strong>，且在进一步微调下</strong>仍持久</strong>——<strong>行为越&quot;宽&quot;、越无法靠定向 SFT 解决时，收益越大</strong>。</p><p>为什么重要：这直击**&quot;对齐税&quot;与&quot;遗忘可逆&quot;<strong>两大现实痛点，把&quot;压制不良行为&quot;从一次性手术变成</strong>可泛化到状态空间的训练目标**。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/index.md</code>（外脑自身的知识治理/纠错机制）呼应；&quot;宽触发 vs 窄触发&quot;可类比 <code>topics/psychology/index.md</code> 中的习惯替换与泛化问题。</p><hr><h3 id="_8-对抗式投机推理-把投机解码从「加速器」变成「上下文精度分配器」" tabindex="-1">8. 对抗式投机推理：把投机解码从「加速器」变成「上下文精度分配器」 <a class="header-anchor" href="#_8-对抗式投机推理-把投机解码从「加速器」变成「上下文精度分配器」" aria-label="Permalink to &quot;8. 对抗式投机推理：把投机解码从「加速器」变成「上下文精度分配器」&quot;">​</a></h3><p><strong>原文</strong>：投机解码一直被视为纯系统优化——加速解码但不改变模型行为，因此「训练更好的草稿模型」只盯着接受率。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>arXiv:2611.05345 (2026)</em>（<strong>未能核实原始出处</strong>）。这篇论文推翻一个行业共识：<strong>投机解码（speculative decoding）&quot;不影响输出分布&quot;</strong>。经典论证成立的前提是<strong>验证器严格接受/拒绝草稿的整段 token</strong>，而一旦进入<strong>长程智能体推理</strong>（几十步思考 + 工具调用），前提就松动了。</p><p>作者的实测发现是<strong>数值噪声累积</strong>：草稿 token 的接受/拒绝结果会<strong>在 30 步之后改变输出分布</strong>，且方向<strong>随机</strong>——也就是说投机解码在长程任务里<strong>悄悄引入了一个不可控的随机扰动源</strong>，而准确率对它是敏感的。</p><p>他们的应对很反直觉：<strong>不消除噪声，而是控制它</strong>。目标是<strong>不改目标模型验证的整体 token 分布</strong>，只训练<strong>草稿模型故意&quot;被拒绝&quot;</strong>，从而把关键推理步骤<strong>逼回目标模型</strong>、以<strong>最高精度</strong>编码。具体：在智能体轨迹中识别这些<strong>关键决策点</strong>，用<strong>对抗性偏好</strong>训练草稿模型；推理时草稿与目标在决策点<strong>精确分道</strong>、<strong>验证重启</strong>，于是关键思考 token 由<strong>目标模型在其最小噪声条件下</strong>采样——等于<strong>把草稿器的角色从&quot;加速&quot;改成&quot;精度调度&quot;</strong>。</p><p>结果（据简讯）：在复杂智能体编码基准上<strong>端到端成功率提升</strong>，且<strong>不动目标模型或其输出分布</strong>，只训练<strong>0.06%–0.28%</strong> 的<strong>托管参数</strong>（hosted parameters）。为什么重要：这是**&quot;系统优化参数 = 可训练的行为控制器&quot;**的一个新范式——把推理时的系统层旋钮纳入训练，代价极低。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code>（推理系统设计）和 <code>topics/ai-brain/knowledge-system-arsenal.md</code>（工具与系统层优化）同源。</p><hr><h3 id="_9-上下文学习-icl-的一个因果电路" tabindex="-1">9. 上下文学习（ICL）的一个因果电路 <a class="header-anchor" href="#_9-上下文学习-icl-的一个因果电路" aria-label="Permalink to &quot;9. 上下文学习（ICL）的一个因果电路&quot;">​</a></h3><p><strong>原文</strong>：上下文学习（ICL）让预训练模型按提示中的示例完成任务、无需更新参数；当标签任意时，模型必须在前向传播内学会一个它不可能记住的映射。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>arXiv:2611.05344 (2026)</em>（<strong>未能核实原始出处</strong>）。可解释性领域的一个老问题：ICL 的&quot;候选部件&quot;（induction head 等）早被找到，但<strong>它们如何组合成一个可跑通的算法</strong>从未被完整刻画。本文在<strong>三个 3–4B 参数 Transformer</strong> 上，用&quot;<strong>任意标签的少样本句子分类</strong>&quot;这个最纯的任务补齐了组合。</p><p>据简讯，完整算法分四步：(1) <strong>键值记忆</strong>——每个<strong>标签 token 的残差流</strong>编码<strong>标签身份</strong>；(2) <strong>写键</strong>——<strong>中层注意力头</strong>把<strong>前一个示例的类别</strong>写成它的<strong>键</strong>；(3) <strong>读出</strong>——在查询处，<strong>上层头</strong>把<strong>查询类别与已存键匹配、复制出对应标签</strong>；(4) <strong>门控</strong>——一个<strong>早期层信号</strong>（编码&quot;是否有标签重复&quot;）<strong>门控读出</strong>：信号缺失时，读者只注意提示开头、不偏向任何标签；另有<strong>一组头抑制最近出现的标签</strong>（防&quot;重复上一个答案&quot;）。</p><p>方法论上也值得记：每一步都用<strong>激活 patch（activation patching）+ 头消融（对随机头基线）+ 用模型自身信号做 steering</strong> 三重手段<strong>因果</strong>确立，而非相关性。更强的证据是<strong>守恒性</strong>——该计算在三个模型间一致，<strong>从头训练的 Transformer 会长出相同部件</strong>，且电路可迁移到<strong>语义概念与有意义的标签</strong>。</p><p>为什么重要：这是把 ICL 从&quot;现象&quot;降维成&quot;<strong>可读出的前向算法</strong>&quot;，为<strong>可解释性驱动的模型编辑</strong>提供了精确的控制点（知道改哪个头能改哪一步）。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/index.md</code>、<code>topics/intelligence-self-learning/index.md</code> 中的表征与学习机制讨论直接对接。</p><hr><h3 id="_10-「无知几何」-用激活碎片化检测-llm-被压制-但仍可恢复-的知识" tabindex="-1">10. 「无知几何」：用激活碎片化检测 LLM 被压制（但仍可恢复）的知识 <a class="header-anchor" href="#_10-「无知几何」-用激活碎片化检测-llm-被压制-但仍可恢复-的知识" aria-label="Permalink to &quot;10. 「无知几何」：用激活碎片化检测 LLM 被压制（但仍可恢复）的知识&quot;">​</a></h3><p><strong>原文</strong>：判断 LLM 是否「真的知道」某概念是根本难题：行为指标会被压制欺骗——拒答的模型可能仍藏有可恢复的知识。</p><p><strong>深度扩展</strong>：</p><p>简讯标注 <em>arXiv:2611.05272 (2026)</em>（<strong>未能核实原始出处</strong>）。这是一个<strong>评测的真问题</strong>：被安全对齐或遗忘（unlearning）过的模型会<strong>拒答</strong>，但拒答 ≠ 不知道——知识可能仍在参数里、只被输出层压住。<strong>行为指标（BBQ/拒答率）会系统性误判</strong>。</p><p>本文提出一个纯<strong>表征层</strong>的度量：<strong>anon-vectors 的几何一致性</strong>。定义是——对某概念构造<strong>概念专属查询</strong>与其<strong>匿名改写</strong>（去掉概念词但保留句式），取两者<strong>隐状态之差</strong>作为 anon-vector；如果一个概念<strong>真的被编码</strong>，这些差值向量会形成<strong>紧致、低熵的簇</strong>；如果模型<strong>其实不知道</strong>，差值就<strong>几何碎片化</strong>（散布、无结构）。用&quot;<strong>无知 = 几何碎片化</strong>&quot;作为物理图像。</p><p>据简讯，在<strong>三个模型族共十个指令微调 LLM</strong> 上，所有碎片化指标都<strong>可靠区分已知/未知概念</strong>；更强的结果在<strong>遗忘后</strong>：碎片化几何与<strong>四类攻击、五种遗忘算法</strong>下的<strong>对抗恢复（adversarial recovery）</strong> 相关（方向依攻击方法而定）；<strong>逐层分析</strong>显示不同对抗机制在<strong>不同深度</strong>利用这种几何，呈现<strong>行为评估看不到的&quot;高攻击特异相关性&quot;</strong>。</p><p>为什么重要：它给了安全评测一个<strong>单相位、免攻击（attack-free）</strong> 的<strong>遗忘稳健性代理指标</strong>——不必真的跑攻击，只看表征几何就能预判&quot;这个被压制的知识有多容易被挖回来&quot;，捕捉到输出层指标完全看不见的参数化知识。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/knowledge-system-arsenal.md</code>（知识表征与治理）及 <code>topics/intelligence-self-learning/single-point-breakthrough.md</code>（表征层的&quot;单点&quot;结构）形成方法学呼应。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><blockquote><p>从本期 10 条中挑 3 条，拆到分子/计算/训练动力学的完整因果链。以下机制描述<strong>均基于当天简讯所给信息</strong>，未联网核验原文（见文首核查说明）。</p></blockquote><h3 id="机制一-核糖体移码如何变成-癌细胞专属开关-对应第-1-条" tabindex="-1">机制一：核糖体移码如何变成&quot;癌细胞专属开关&quot;（对应第 1 条） <a class="header-anchor" href="#机制一-核糖体移码如何变成-癌细胞专属开关-对应第-1-条" aria-label="Permalink to &quot;机制一：核糖体移码如何变成&quot;癌细胞专属开关&quot;（对应第 1 条）&quot;">​</a></h3><p><strong>分子基础</strong>：翻译时，核糖体沿 mRNA 的 <strong>3 个核苷酸 = 1 个密码子</strong> 的<strong>阅读框</strong>前进。−1 移码意味着核糖体在某个位置<strong>回退一个碱基</strong>、此后以新框翻译——<strong>同一段 mRNA 读出完全不同的蛋白</strong>。病毒（HIV 的 gag-pol、冠状病毒的 ORF1a/1b）靠这个机制把结构蛋白与酶调成精确比例，是<strong>用 RNA 序列编码的&quot;化学计量调节器&quot;</strong>。</p><p><strong>为什么会在癌细胞里被放大</strong>（简讯给出的因果链，共三步）：</p><ol><li><strong>序列层</strong>——<strong>特定密码子对（codon pair）<strong>构成移码&quot;热点&quot;。这决定了移码</strong>只在特定 mRNA 序列上、以可预测的效率发生</strong>，是可设计的输入。</li><li><strong>动力学层</strong>——移码发生在<strong>核糖体暂停</strong>时。核糖体在两个密码子交界处若因等待<strong>稀有 tRNA</strong> 或<strong>氨基酸供给不足</strong>而停顿，就给了 mRNA 滑移一个 −1 碱基的时间窗。因此移码率是<strong>tRNA 池 + 氨基酸可用性</strong>的函数——而癌细胞代谢重编程恰好剧烈改变了这两者。</li><li><strong>质量放大层</strong>——<strong>受损的核糖体质量控制（RQC）<strong>本来负责清除卡壳核糖体，它的失灵让&quot;停顿&quot;更容易转化为&quot;移码&quot;；同时</strong>核糖体蛋白 S6 的持续磷酸化</strong>（mTOR 通路活跃的标志）与翻译失调叠加。三者合起来，使<strong>密码子对特异的移码成为癌细胞普遍存在的内禀状态</strong>。</li></ol><p><strong>工程化（FAST）</strong>：把上述&quot;内禀状态&quot;当作<strong>逻辑门</strong>——设计一条 mRNA，其<strong>功能蛋白（gasdermin D）的阅读框只有在发生 −1 移码时才对齐</strong>。于是：正常细胞 → 不移码 → 读出错框废肽；癌细胞 → 高移码 → 读出完整 <strong>gasdermin D</strong> → 在膜上打孔 → <strong>焦亡（pyroptosis）</strong>，一种<strong>高度免疫原性</strong>的细胞死亡，会释放 DAMPs 激活抗原呈递。这就是&quot;<strong>选择性</strong>&quot;的来源：<strong>不需要癌细胞独有的靶点，只需要癌细胞独有的翻译状态</strong>。AAV9 递送 + 与检查点阻断协同的结果（简讯报告小鼠结直肠癌/胰腺癌显著消退）与焦亡的免疫激活属性自洽。</p><p><strong>可证伪预测</strong>：若机制成立，人为<strong>抑制 S6 磷酸化或恢复 RQC</strong> 应<strong>降低</strong> FAST 在癌细胞中的激活强度——这是一个可直接检验的干预-响应关系。</p><h3 id="机制二-icl-的-读写-门控-四步算法-对应第-9-条" tabindex="-1">机制二：ICL 的&quot;读写-门控&quot;四步算法（对应第 9 条） <a class="header-anchor" href="#机制二-icl-的-读写-门控-四步算法-对应第-9-条" aria-label="Permalink to &quot;机制二：ICL 的&quot;读写-门控&quot;四步算法（对应第 9 条）&quot;">​</a></h3><p>Transformer 的前向传播里没有梯度、也没有参数更新，ICL 必须在<strong>一次前向</strong>内完成&quot;看示例→归纳映射→应用&quot;。</p><p><strong>第 1 步 · 写键（知识编码）</strong>：每个<strong>示例的标签 token</strong> 在自己的<strong>残差流</strong>位置留下一个<strong>编码&quot;标签身份&quot;<strong>的向量；<strong>中层注意力头</strong>再把这个向量与</strong>该示例的类别（如&quot;这是褒义句&quot;）<strong>关联起来，<strong>写成一条&quot;键→值&quot;记录</strong>。相当于模型在</strong>上下文窗口内拼出一张查找表</strong>。</p><p><strong>第 2 步 · 查询匹配</strong>：到<strong>待分类的查询句</strong>处，<strong>上层注意力头</strong>计算查询的类别表征，与上述<strong>所有已存键</strong>做匹配——匹配方式与 <strong>induction head</strong>（&quot;找到相同前缀、复制其后继&quot;）同源，但此处匹配的是<strong>类别</strong>而非 token 串。</p><p><strong>第 3 步 · 复制读出</strong>：匹配到键后，把对应的<strong>标签复制到输出位置</strong>。这是<strong>无需学习新权重</strong>的&quot;检索式&quot;映射。</p><p><strong>第 4 步 · 门控与抑制</strong>：一个<strong>早期层信号</strong>（编码&quot;提示里是否存在标签重复&quot;）<strong>门控</strong>整个读出——若信号缺失，读者<strong>只注意提示开头、不偏向任何标签</strong>（即模型&quot;放弃&quot;了归纳）；同时<strong>一组头专门抑制最近出现的标签</strong>，防止退化成&quot;抄上一个标签&quot;的平凡策略。</p><p><strong>为什么这是&quot;因果电路&quot;而非相关性</strong>：简讯强调每一步都用<strong>激活 patch、头消融（对随机头基线）、模型自身信号 steering</strong> 验证；更关键的是<strong>守恒性</strong>——三个不同模型长出的部件<strong>相同</strong>，从头训练的 Transformer <strong>也会长出同样结构</strong>。这说明该电路不是某个 checkpoint 的偶然preference，而是<strong>任务 + 架构共同决定的必然解</strong>。</p><h3 id="机制三-pearl-为何让-压制-更持久-对应第-7-条" tabindex="-1">机制三：PEARL 为何让&quot;压制&quot;更持久（对应第 7 条） <a class="header-anchor" href="#机制三-pearl-为何让-压制-更持久-对应第-7-条" aria-label="Permalink to &quot;机制三：PEARL 为何让&quot;压制&quot;更持久（对应第 7 条）&quot;">​</a></h3><p><strong>问题动力学</strong>：对齐/压制之所以会<strong>复发</strong>，是因为它通常只在<strong>观测到的那些状态</strong>上被施加（典型 SFT：只训练&quot;坏提示 → 好回答&quot;这一条路径）。一旦模型被推到<strong>中间状态</strong>（生成了半段不安全推理），它其实<strong>从未被训练过如何回头</strong>——于是&quot;越写越偏&quot;。</p><p><strong>PEARL 的机制</strong>：它把 rollout 的<strong>起点</strong>从提示位置<strong>前移到轨迹的中间状态</strong>——即<strong>缓存已有轨迹的中间状态、从那里续写</strong>。这样训练分布从<strong>单一入口</strong>扩展为<strong>一族入口状态</strong>，模型被迫在<strong>更广的失准状态集合</strong>上学习&quot;如何恢复&quot;。</p><p><strong>为什么&quot;宽&quot;比&quot;窄&quot;更受益</strong>：窄触发型失准（只在特定线索下出错）可以被<strong>定向 SFT</strong> 精准覆盖——你只要枚举那个线索即可；而<strong>宽触发型</strong>（不安全代码微调后的广泛有害响应）无法枚举，其失准状态<strong>弥散在整个状态空间</strong>。PEARL 的 prefix 扩展正是<strong>对状态空间做覆盖</strong>，因此收益随&quot;宽&quot;度上升——这解释了简讯中&quot;行为越宽、收益越大&quot;的经验结果。</p><p><strong>与 GRPO 的关系</strong>：GRPO 是<strong>基于组内相对优势</strong>的策略梯度，对<strong>同一提示的多次采样</strong>做归一化。PEARL 保留这一骨架，但把&quot;组&quot;的成员换成<strong>来自同一轨迹不同中间状态</strong>的续写——相当于把<strong>对比学习的思想搬到状态轴</strong>，而不是采样轴。三个准则（即时压制 / 持久性 / 能力保持）同时满足，说明这条路径<strong>没有用能力换安全</strong>。</p><hr><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><blockquote><p>挑 2 条，退到物理定律与可证伪预测层面。</p></blockquote><h3 id="原理一-为什么-更短的脉冲-必然换来-更宽的谱-——170-阿秒的物理上限-对应第-3-条" tabindex="-1">原理一：为什么&quot;更短的脉冲&quot;必然换来&quot;更宽的谱&quot;——170 阿秒的物理上限（对应第 3 条） <a class="header-anchor" href="#原理一-为什么-更短的脉冲-必然换来-更宽的谱-——170-阿秒的物理上限-对应第-3-条" aria-label="Permalink to &quot;原理一：为什么&quot;更短的脉冲&quot;必然换来&quot;更宽的谱&quot;——170 阿秒的物理上限（对应第 3 条）&quot;">​</a></h3><p><strong>第一性原理是傅里叶不确定性</strong>：对任何脉冲，<strong>时域宽度 Δt 与频域带宽 Δω 满足 Δt·Δω ≳ 1/2</strong>（高斯脉冲取等号，即&quot;变换极限&quot;）。这条关系<strong>不是技术缺陷，而是傅里叶变换的数学必然</strong>——一个在时间上极窄的信号，必然由极宽的频率成分叠加而成。这就是简讯中&quot;<strong>宽带 X 射线分束</strong>&quot;是必需而非可选的原因：<strong>要造 170 as 的脉冲，你必须有横跨极宽能带的硬 X 射线</strong>。</p><p>由此可推出三个不可绕过的约束：</p><ol><li><strong>计量必须用相关法</strong>——脉冲短于任何电子探测器的响应时间（探测器带宽仅到 ps 量级，比 170 as 慢 <strong>4 个数量级</strong>），因此<strong>直接计时不可能</strong>。唯一出路是<strong>把两束光在时间上错开、测它们如何干涉/相关</strong>（场关联、强度自相关），用<strong>已知延迟</strong>反推<strong>未知脉宽</strong>——这正是本文的方法论必然性。</li><li><strong>非线性探针的稀缺性</strong>——阿秒时间尺度上，只有<strong>非线性光学过程</strong>（此处是<strong>非顺序双光子吸收</strong>）才能&quot;在脉冲自身持续时间内&quot;做出响应，因为它要求<strong>两个光子在同一个脉冲的时间窗内同时到达</strong>。脉冲越短，该过程越弱——这解释了为何硬 X 射线阿秒计量长期难做。</li><li><strong>可证伪预测</strong>：若脉冲确为变换极限，则<strong>实测相干时间 × 实测带宽 ≈ 常数</strong>。任何测量若给出远超此乘积的相干时间，即意味着脉冲<strong>不是傅里叶极限</strong>（有啁啾），可被独立的色散测量交叉检验。</li></ol><p><strong>深层统一</strong>：这条原理与量子力学的 <strong>Δx·Δp ≳ ℏ/2</strong> 同源——都是共轭变量之间的<strong>傅里叶对偶</strong>。区别只在量纲：一个约束时间-频率，一个约束位置-动量。理解了&quot;要看清快的东西，必须用宽的东西去探&quot;，就理解了为什么阿秒科学<strong>天然绑定</strong>宽带光源与非线性探测。</p><h3 id="原理二-贝尔不等式违背-2-455-2-究竟排除了什么-对应第-4-条" tabindex="-1">原理二：贝尔不等式违背 2.455 &gt; 2 究竟排除了什么（对应第 4 条） <a class="header-anchor" href="#原理二-贝尔不等式违背-2-455-2-究竟排除了什么-对应第-4-条" aria-label="Permalink to &quot;原理二：贝尔不等式违背 2.455 &gt; 2 究竟排除了什么（对应第 4 条）&quot;">​</a></h3><p><strong>要排除的假设</strong>：<strong>局域实在论（local realism）</strong>，由两条看似无懈可击的直觉组成——</p><ul><li><strong>实在性（realism）</strong>：测量前，物理量已有确定取值（&quot;月亮不看它也在那儿&quot;）；</li><li><strong>局域性（locality）</strong>：远处的事件不可能瞬时影响此处（无超光速信号）。</li></ul><p><strong>贝尔的贡献</strong>是把它变成一个<strong>可测量的不等式</strong>：在局域实在论下，某些<strong>测量组合的相关性</strong>（CHSH 形式的 <strong>S 参数</strong>）<strong>必然满足 S ≤ 2</strong>。这条不等式之所以强力，是因为它<strong>不依赖量子力学的具体形式</strong>——任何局域隐变量理论都必须遵守它。</p><p><strong>本文的意义就在这一步</strong>：观测到 <strong>S = 2.455(77) &gt; 2</strong>（括号内为统计不确定度最后两位，即 ≈ 0.077），是<strong>对局域实在论的直接实验排除</strong>，而非仅仅&quot;制备了一个高保真纠缠态&quot;。简讯同时给出的 <strong>91.4% 保真度</strong>是<strong>态质量</strong>指标——两者独立：保真度高≠一定违背不等式（探测效率不足时，即使态很纯，也测不出违背；这正是&quot;探测漏洞 detection loophole&quot;的来源）。</p><p><strong>为什么必须做在电信波段</strong>：这是一条<strong>工程-物理耦合的必然性</strong>——光纤在 1550 nm 附近损耗最低（~0.2 dB/km），因此任何<strong>长距离</strong>纠缠分发都要求飞行光子落在 <strong>C 波段</strong>。而量子力学本身<strong>不区分波段</strong>，所以把发射体做到 1530 nm（铷的偶极跃迁）<strong>纯粹是为了让物理可行</strong>。此前需<strong>频率转换</strong>（会引入噪声、拉低保真度），直接发射因此在<strong>物理上更干净</strong>。</p><p><strong>可证伪预测</strong>：若该纠缠真具非局域性且无漏洞，则在<strong>加入局部性/探测效率</strong>约束的更强不等式（如设备无关 QKD 的安全界）下，<strong>密钥率应保持正</strong>；若结果由探测效率漏洞伪造，则收紧效率条件后应<strong>坍缩到经典界以下</strong>。</p><hr><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p>本期 10 条看似横跨免疫治疗、拓扑材料、阿秒物理、量子非局域性、行星地质与大模型对齐，但它们共享<strong>一条统一逻辑</strong>：</p><p><strong>「利用系统的内禀状态/内禀结构作为可寻址的信号，而非依赖外部标签。」</strong></p><p>逐条验证这条逻辑：</p><ul><li><strong>第 1 条（FAST）</strong>：不找癌细胞独有靶点，而是<strong>读癌细胞独有的翻译内禀状态</strong>（移码率）。信号来自疾病状态本身。</li><li><strong>第 2 条（三轴编织）</strong>：性质不由成分配方决定，而由<strong>编织拓扑这一内禀自由度</strong>决定——换拓扑而非换元素。</li><li><strong>第 4 条（电信纠缠）</strong>：不靠外部频率转换&quot;改造&quot;光子，而是<strong>让铷原子直接发射电信波长</strong>——用发射体的内禀跃迁匹配光纤的物理最优窗口。</li><li><strong>第 5 条（火星 HCl）</strong>：不看被光化学快速抹除的 SO₂，而是用<strong>更稳定的 HCl</strong>去读岩浆房的&quot;内禀指纹&quot;，并把<strong>冷季 + 局域</strong>两个反常当作信号本体。</li><li><strong>第 7/8 条（PEARL / 对抗投机）</strong>：不改目标模型的输出分布，而是<strong>操控训练/推理的内禀状态分布</strong>（轨迹中间状态起点、草稿的拒绝位置）来改变行为。</li><li><strong>第 9/10 条（ICL 电路 / 无知几何）</strong>：不靠行为输出去问&quot;模型会不会&quot;，而是<strong>直接读残差流与隐状态的几何</strong>——把内禀表征当作判据。</li><li><strong>第 3 条（阿秒计量）</strong>：器件无法计时，就转而<strong>用光自身的时间相关性</strong>去测光——信号与时标同源。</li></ul><p><strong>与库内主题的深层同构</strong>：</p><ol><li><strong>与「约束维护」主线同构</strong>（参见 <code>topics/biomedicine/index.md</code> 与往期深度扩展中的 EatA/黏液层分析）：第 1 条把&quot;癌细胞 RQC 失灵&quot;这一<strong>约束破损</strong>反过来用作<strong>选择器</strong>；而第 7 条说明<strong>压制若只覆盖部分状态（约束不完整）就会复发</strong>——两者是同一命题的两面：<strong>系统的稳定行为取决于约束作用的状态空间覆盖度</strong>。</li><li><strong>与「表征即知识」主线同构</strong>：第 9、10 条与 <code>topics/intelligence-self-learning/index.md</code>、<code>topics/ai-brain/knowledge-system-arsenal.md</code> 一脉相承——<strong>知识的位置在表征几何里，而非在输出文本里</strong>。这与本知识库自身的组织哲学（<code>topics/</code> + <code>links/</code>，靠<strong>关联结构</strong>而非<strong>孤立条目</strong>承载知识）形成直接映射：<strong>碎片化的笔记 = 无知几何；紧致的关联簇 = 真知识</strong>。</li><li><strong>与「用时间/频率换本征信息」同构</strong>：第 3 条（阿秒）与第 4 条（电信波段）都在<strong>共轭变量之间做取舍</strong>——前者在<strong>时间-频率</strong>域，后者在<strong>波长-损耗</strong>域；共同点是<strong>不逃避物理约束，而是让约束决定架构</strong>。</li></ol><p><strong>一句话收束</strong>：本期最强的跨域信号是——<strong>&quot;读内禀状态&quot;正在取代&quot;贴外部标签&quot;</strong>，无论在癌细胞、光子、行星大气还是 Transformer 的残差流里。</p><hr><p>关键词：核糖体移码, ribosomal frameshifting, FAST, gasdermin D, 焦亡, pyroptosis, 密码子对, codon pair, 核糖体质量控制, RQC, S6 磷酸化, 分子编织, molecularly woven fabric, 三轴编织, topological chirality, 拓扑手性, B–N 配位聚合, C₃ 对称大环, 阿秒, attosecond, 硬 X 射线, XFEL, 自由电子激光, 非顺序双光子吸收, 强度自相关, 170 as, 10.1038/s41586-026-11245-5, 自旋—光子纠缠, spin–photon entanglement, 贝尔非局域性, Bell nonlocality, 贝尔不等式违背, CHSH, 电信 C 波段, 铷原子, 1530 nm, 腔辅助协议, 保真度 91.4%, 10.1038/s41467-026-79099-z, 火星 HCl, Alba Mons, 阿尔巴山, 岩浆活动, Science Advances, 10.1126/sciadv.aeb9422, DreamX, 潜动作, latent action, 视频扩散模型, LARY-Bench, 跨具身迁移, arXiv:2611.05377, PEARL, Prefix-Expanded Adversarial RL, GRPO, 对齐浅层性, alignment shallowness, 模式生物, model organisms, Qwen3-4B, GPT-OSS-20B, arXiv:2611.05358, 投机解码, speculative decoding, 对抗式投机推理, 托管参数, arXiv:2611.05345, 上下文学习, ICL, induction head, 激活 patch, 头消融, residual stream, 残差流, arXiv:2611.05344, 无知几何, anon-vectors, 激活碎片化, activation fragmentation, 遗忘, unlearning, arXiv:2611.05272, 10.1038/s41586-026-11200-4, 10.1038/s41586-026-11218-8, Nature, Nature Communications</p><p>关联：topics/biomedicine/index.md, topics/biomedicine/anastasis-cancer-cell-recovery.md, topics/biomedicine/science-daily-2026-11-05-biomed.md, topics/materials/index.md, topics/physics/advanced-materials-deep.md, topics/physics/spectroscopy.md, topics/physics/science-daily-2026-11-05-physics.md, topics/quantum-physics/index.md, topics/quantum-physics/macro-entanglement-2026.md, topics/quantum-physics/science-daily-2026-11-05-quantum.md, topics/earth-science/index.md, topics/earth-science/science-daily-2026-11-05-earth.md, topics/space-energy/index.md, topics/paleontology/index.md, topics/ai-brain/index.md, topics/ai-brain/knowledge-system-arsenal.md, topics/ai-system-architecture/index.md, topics/intelligence-self-learning/index.md, topics/intelligence-self-learning/single-point-breakthrough.md, topics/psychology/index.md, topics/science-news/index.md</p>',136)])])}const q=t(g,[["render",e]]);export{d as __pageData,q as default};
